INSERT INTO supplier SELECT * REPLACE (s_suppkey + 3000000000 AS s_suppkey) FROM supplier WHERE s_suppkey IN (SELECT ps_suppkey FROM partsupp WHERE ps_partkey < 2147483648 AND ps_partkey % 8 = 0) AND NOT EXISTS (SELECT 1 FROM supplier AS c WHERE c.s_suppkey = supplier.s_suppkey + 3000000000);
INSERT INTO part SELECT * REPLACE (p_partkey + 3000000000 AS p_partkey) FROM part WHERE p_partkey < 2147483648 AND p_partkey % 8 = 0 AND NOT EXISTS (SELECT 1 FROM part AS c WHERE c.p_partkey = part.p_partkey + 3000000000);
INSERT INTO partsupp SELECT * REPLACE (ps_partkey + 3000000000 AS ps_partkey, ps_suppkey + 3000000000 AS ps_suppkey) FROM partsupp WHERE ps_partkey < 2147483648 AND ps_partkey % 8 = 0 AND NOT EXISTS (SELECT 1 FROM partsupp AS c WHERE c.ps_partkey = partsupp.ps_partkey + 3000000000 AND c.ps_suppkey = partsupp.ps_suppkey + 3000000000);
